	["glances skyward out of habit."] = "mira al cielo por costumbre.",
	["glances up at the branches overhead, as though one of them might move."] = "mira las ramas de arriba, como si alguna fuera a moverse.",
	["glances up past the reach of the firelight, as if counting something overhead."] = "levanta la vista más allá del alcance de la luz del fuego, como si contara algo en lo alto.",
	["glances up, as if at a high window, and flinches."] = "mira hacia arriba, como a una ventana alta, y da un respingo.",
	["goes completely still for a long moment, barely breathing."] = "se queda completamente inmóvil un largo momento, casi sin respirar.",
	["goes completely still, one hand flat at their side, eyes fixed on nothing."] = "se queda completamente inmóvil, con una mano pegada al costado y la mirada perdida.",
	["goes quiet and lowers their eyes to the flames."] = "se queda en silencio y baja la mirada a las llamas.",
	["goes quiet, letting the crackle of the fire fill the place where the answer would be."] = "se queda en silencio y deja que el crepitar del fuego ocupe el lugar de la respuesta.",
	["goes very still, and looks down at their empty hands."] = "se queda inmóvil y se mira las manos vacías.",
	["grabs at something over their shoulder and leans back with all their weight."] = "agarra algo por encima del hombro y se echa hacia atrás con todo su peso.",
	["grabs at the air with both hands, then wrenches them sharply to one side."] = "agarra el aire con las dos manos y tira de golpe hacia un lado.",
	["grins across the fire."] = "sonríe de oreja a oreja al otro lado del fuego.",
	["grins and takes a long, satisfied drink."] = "sonríe y echa un trago largo y satisfecho.",
	["grins wide, showing every tooth, and holds it a little too long."] = "sonríe de oreja a oreja, enseñando todos los dientes, y aguanta la sonrisa un poco más de la cuenta.",
	["grins, then hides the grin behind one hand."] = "sonríe, y luego esconde la sonrisa tras una mano.",
	["grips an imaginary set of levers and jerks them left and right."] = "agarra unas palancas imaginarias y las mueve a tirones a izquierda y derecha.",
	["grips an imagined club and gives one short, checked swing above their knee."] = "empuña un garrote imaginario y da un golpe corto y contenido por encima de la rodilla.",
	["grips an invisible rope in both fists, and leans back hard."] = "aprieta una cuerda invisible con los dos puños y tira hacia atrás con fuerza.",
	["grips an invisible sack by the neck and swings it round in a wide, low arc."] = "agarra un saco invisible por la boca y lo hace girar en un arco amplio y bajo.",
	["grips an invisible staff that keeps trying to tilt to one side, and wrestles it upright."] = "agarra un bastón invisible que no para de ladearse y lo endereza a la fuerza.",
	["grips an invisible totem in both hands and drives it into the ground beside them."] = "agarra un tótem invisible con las dos manos y lo clava en el suelo a su lado.",
	["grips reins and leans sharply to one side, cheeks puffed."] = "agarra unas riendas y se inclina bruscamente hacia un lado, con los carrillos hinchados.",
	["grunts, a smile tugging at one tusk."] = "gruñe, y una sonrisa le asoma por un colmillo.",
	["gurgles deep in their throat, then wipes their chin with great dignity."] = "suelta un gorgoteo desde el fondo de la garganta y luego se limpia la barbilla con muchísima dignidad.",
	["hauls hand over hand on an invisible rope, leaning back."] = "tira de una cuerda invisible mano sobre mano, echándose hacia atrás.",
	["hefts an invisible, very heavy volume in both hands and squares up."] = "sopesa con las dos manos un tomo invisible y pesadísimo, y se planta en guardia.",
	["holds a flat hand low, then lets it slowly rise and sway."] = "sostiene una mano plana a poca altura y luego la deja subir y mecerse despacio.",
	["holds a hand out over the coals, palm down, and slowly draws it back."] = "extiende una mano sobre las brasas, con la palma hacia abajo, y la retira despacio.",
	["holds an invisible crate out at arm's length and leans their head away from it."] = "sostiene una caja invisible con los brazos estirados y aparta la cabeza de ella.",
	["holds an invisible drawing out at arm's length and tilts their head at it."] = "sostiene un dibujo invisible con el brazo estirado y ladea la cabeza para mirarlo.",
	["holds an invisible umbrella high overhead and squints up at it."] = "sostiene una sombrilla invisible bien alta y la mira con los ojos entornados.",
	["holds an invisible vial up to the light."] = "levanta un vial invisible hacia la luz.",
	["holds both arms out wide and lets them sink slowly, counting with small nods."] = "abre los brazos de par en par y los deja descender despacio, contando con pequeños gestos de la cabeza.",
	["holds both hands close together above the warmth."] = "junta las dos manos sobre el calor.",
	["holds both hands out toward the flames."] = "tiende las dos manos hacia las llamas.",
	["holds both palms out toward the fire, as if feeling warmth from something unseen."] = "acerca las palmas al fuego, como si notara el calor de algo invisible.",
	["holds both palms toward the fire for a long moment, as if checking that they still feel it."] = "tiende ambas palmas hacia el fuego un largo rato, como para comprobar que aún lo sienten.",
	["holds one boot out toward the flames and regards it with long-suffering sadness."] = "acerca una bota a las llamas y la contempla con una tristeza resignada.",
	["holds one elbow up to the firelight and studies it for a long moment."] = "levanta un codo hacia la luz del fuego y lo examina un buen rato.",
	["holds one finger very still above an open palm, waiting."] = "mantiene un dedo muy quieto sobre la palma abierta, esperando.",
	["holds one forearm close against their chest, and reaches carefully up with the other."] = "se pega un antebrazo al pecho y alarga con cuidado la otra mano hacia arriba.",
	["holds one hand flat above their head and squints up from beneath it."] = "pone una mano plana sobre la cabeza y mira hacia arriba por debajo, con los ojos entornados.",
	["holds one hand halfway raised, eyes moving slowly left and right."] = "deja una mano a medio levantar, moviendo los ojos despacio de izquierda a derecha.",
	["holds one hand out to the fire, the other still on the pouch, and seems unsure which is warmer."] = "acerca una mano al fuego, con la otra aún sobre la bolsita, y no parece saber cuál está más caliente.",
	["holds one open palm out toward the fire, as if to have it read."] = "tiende la palma abierta hacia el fuego, como para que se la lean.",
	["holds out a cupped hand and drops invisible nails into it, one at a time."] = "extiende una mano ahuecada y deja caer en ella clavos invisibles, de uno en uno.",
	["holds out a cupped hand, then slowly pushes it away."] = "tiende una mano ahuecada y luego la aparta despacio.",
	["holds out a hand, as if feeling for a breeze."] = "extiende una mano, como buscando la brisa.",
	["holds out an empty palm toward the fire, hopefully."] = "tiende la palma vacía hacia el fuego, con esperanza.",
	["holds out an invisible pen across the fire toward {target}."] = "tiende una pluma invisible por encima del fuego hacia {target}.",
	["holds out an invisible spoon toward {target} with both hands, like a knight offering a sword."] = "tiende un cucharón invisible hacia {target} con las dos manos, como un caballero que ofrece su espada.",
	["holds out both hands and accepts something small, with visible surprise."] = "tiende las dos manos y acepta algo pequeño, con cara de sorpresa.",
	["holds out both hands and regards them quietly."] = "extiende las dos manos y las contempla en silencio.",
	["holds out both hands as if warming a coat before a fire, turning it slowly."] = "extiende las dos manos como si calentara un abrigo ante el fuego, dándole vueltas despacio.",
	["holds out cupped hands toward {target}, as if passing a bowl across the fire."] = "tiende las manos ahuecadas hacia {target}, como si le pasara un cuenco por encima del fuego.",
	["holds out cupped hands, very still."] = "tiende las manos ahuecadas, sin moverse lo más mínimo.",
	["holds out one arm and scratches the air gently with the other hand."] = "extiende un brazo y rasca el aire con suavidad con la otra mano.",
	["holds out one arm, very still, and looks along it."] = "extiende un brazo, muy quieto, y sigue su línea con la mirada.",
	["holds out one hand as if guiding someone frail across a road."] = "tiende una mano como si ayudara a alguien frágil a cruzar un camino.",
	["holds out one open palm and watches it closely."] = "extiende la palma abierta y la observa con atención.",
	["holds still, then glances toward their own shadow and quickly back to the fire."] = "no se mueve, luego mira de reojo su propia sombra y vuelve rápido la vista al fuego.",
	["holds the back of one hand up to the firelight so an old scar shows, and looks at it for a while."] = "levanta el dorso de una mano a la luz del fuego para que se vea una vieja cicatriz, y la mira un rato.",
	["holds the letter a moment too near the flames, then folds it carefully and tucks it away again."] = "acerca la carta a las llamas un instante de más, luego la dobla con cuidado y la vuelve a guardar.",
	["holds their hands apart as though measuring a very fine pair of boots."] = "separa las manos como si midiera un par de botas finísimas.",
	["holds their hands close to the flames, turns them over, and regards them in silence."] = "acerca las manos a las llamas, les da la vuelta y las contempla en silencio.",
	["holds their palms out to the flames and nods toward {target}'s side of the fire."] = "acerca las palmas a las llamas y señala con la cabeza el lado del fuego de {target}.",
	["holds two fingers very still, then twitches them a hair to one side, timing something."] = "mantiene dos dedos muy quietos y luego los mueve un pelo hacia un lado, calculando el momento.",
	["holds two invisible halves apart and looks from one to the other."] = "sostiene dos mitades invisibles separadas y mira de una a otra.",
	["holds up a hand and counts along their fingers, then starts on the other hand."] = "levanta una mano y va contando con los dedos, y luego sigue con la otra mano.",
	["holds up a hand with the thumb and finger a few inches apart, and smiles."] = "levanta una mano con el pulgar y el índice separados un palmo escaso, y sonríe.",
	["holds up a small steel washer between finger and thumb."] = "sostiene una pequeña arandela de acero entre el índice y el pulgar.",
	["holds up a thumb and finger, pinching something thin and small."] = "levanta el pulgar y el índice, pellizcando algo fino y pequeño.",
	["holds up a thumb and forefinger, barely apart."] = "levanta el pulgar y el índice, casi juntos.",
	["holds up a thumb and squints along it, measuring someone from a distance."] = "levanta un pulgar y guiña un ojo, como si midiera a alguien a distancia.",
	["holds up a tiny invisible stone and squints at it."] = "sostiene en alto una piedrecita invisible y la mira entornando los ojos.",
	["holds up an imaginary blade, squints along it, and grimaces."] = "sostiene una hoja imaginaria, la mira de canto con los ojos entornados y hace una mueca.",
	["holds up an invisible carving and turns it around, frowning, trying another angle."] = "sostiene una talla invisible y le da vueltas, con el ceño fruncido, probando otro ángulo.",
	["holds up an invisible scrap between two fingers."] = "sostiene en alto un retal invisible entre dos dedos.",
	["holds up an invisible vial and squints at it against the firelight."] = "sostiene en alto un vial invisible y lo mira con los ojos entornados a la luz del fuego.",
	["holds up an invisible waterskin and shakes it, listening closely."] = "levanta un odre invisible y lo agita, escuchando con atención.",
	["holds up one finger and lets the question hang in the smoke."] = "levanta un dedo y deja la pregunta flotando en el humo.",
	["holds up one finger, as if the worst part is coming."] = "levanta un dedo, como si ahora viniera lo peor.",
	["holds up one finger, thinks better of it, and opens both hands."] = "levanta un dedo, se lo piensa mejor y abre las dos manos.",
	["holds up one hand and slowly closes it into a loose fist, not a tight one."] = "levanta una mano y la cierra despacio en un puño suelto, sin apretar.",
	["holds up one hand as though steadying a lamp, and keeps it very still."] = "levanta una mano como si sostuviera un farol, y la mantiene muy quieta.",
	["holds up one hand with the fingers spread, studying it as though it belonged to someone else."] = "levanta una mano con los dedos abiertos y la estudia como si fuera de otra persona.",
	["holds up something small between finger and thumb, turning it so the firelight slides along it."] = "levanta algo pequeño entre el índice y el pulgar, girándolo para que la luz del fuego resbale por él.",
	["holds up three fingers, then folds them down, one at a time."] = "levanta tres dedos y luego los dobla, de uno en uno.",
	["holds up two empty fists and stares at them in remembered horror."] = "levanta dos puños vacíos y los mira con el horror del recuerdo.",
	["holds up two fingers, side by side, and gazes at them fondly."] = "levanta dos dedos, uno junto al otro, y los mira con cariño.",
	["holds up two fingers, then knocks them together."] = "levanta dos dedos y luego los entrechoca.",
	["holds up two fingers, then slowly lowers one of them."] = "levanta dos dedos y luego baja uno muy despacio.",
	["hums a few bars of an old marching song."] = "tararea unos compases de una vieja marcha militar.",
	["hums a few wandering notes that never quite settle into a song."] = "tararea unas notas errantes que nunca llegan a ser una canción.",
	["hums the last notes again, more softly."] = "vuelve a tararear las últimas notas, más bajito.",
	["hunches low and leans slowly forward, inch by inch."] = "se agacha mucho y se inclina despacio hacia delante, centímetro a centímetro.",
	["hunches low and moves their hands slowly, as if sneaking."] = "se agacha mucho y mueve las manos despacio, como si se colara a escondidas.",
	["hunches low, gripping the air on either side and refusing to look down."] = "se agacha, agarrándose al aire a ambos lados y negándose a mirar abajo.",
	["hunches low, grips an invisible rim, and leans hard into a turn."] = "se agacha, se agarra a un borde invisible y se inclina con fuerza hacia una curva.",
	["hunches low, one hand out for balance, and glances back with wide eyes."] = "se agacha mucho, con una mano extendida para mantener el equilibrio, y mira hacia atrás con los ojos muy abiertos.",
	["hunches their shoulders and bares their teeth, growling softly."] = "encoge los hombros y enseña los dientes, gruñendo por lo bajo.",
	["is quiet for a moment, then nods slowly."] = "se queda en silencio un momento y luego asiente despacio.",
	["is quiet for a moment, watching the coals."] = "se queda en silencio un momento, mirando las brasas.",
	["is quiet for a moment."] = "se queda en silencio un momento.",
	["jabs a thumb over one shoulder, toward some ridge in the dark."] = "señala con el pulgar por encima del hombro, hacia alguna cresta en la oscuridad.",
	["jerks forward suddenly, one arm wrenched out straight, teeth bared."] = "se va de golpe hacia delante, con un brazo estirado de un tirón y los dientes apretados.",
	["jerks one fist forward, then draws back an imagined blade with the other hand."] = "lanza un puño hacia delante y luego retira con la otra mano una espada imaginaria.",
	["keeps their eyes on the flames, as if still holding that light up for someone."] = "no aparta la vista de las llamas, como si aún sostuviera esa luz para alguien.",
	["keeps their gaze fixed on the ground as they speak."] = "mantiene la mirada clavada en el suelo mientras habla.",
	["knocks twice on the ground beside them."] = "da dos golpes en el suelo, a su lado.",
	["laughs quietly into one hand."] = "se ríe por lo bajo tapándose la boca con una mano.",
	["lays an invisible flower down beside them, very carefully."] = "deja con mucho cuidado una flor invisible a su lado.",
	["lays one hand flat on the ground, then the other beside it."] = "apoya una mano plana en el suelo, y luego la otra a su lado.",
	["lays one hand flat, then sets the other on top of it, very carefully."] = "pone una mano plana y coloca la otra encima, con muchísimo cuidado.",
	["leans back and looks toward the water."] = "se echa hacia atrás y mira hacia el agua.",
	["leans back and stretches both hands toward the warmth."] = "se recuesta y estira las dos manos hacia el calor.",
	["leans back with both hands behind their head."] = "se recuesta con las dos manos detrás de la cabeza.",
	["leans back, still studying {target}, one eye narrowed."] = "se echa hacia atrás, sin dejar de estudiar a {target}, con un ojo entornado.",
	["leans down and lays two fingers on the ground, then goes very still."] = "se agacha, apoya dos dedos en el suelo y se queda inmóvil.",
	["leans down and presses one palm flat against the ground."] = "se agacha y apoya la palma de la mano en el suelo.",
	["leans down and studies the ground, then glances up, smirking."] = "se agacha a estudiar el suelo y luego levanta la vista con una sonrisita.",
	["leans forward and lowers their voice, one eye on the dark beyond the fire."] = "se inclina hacia delante y baja la voz, con un ojo puesto en la oscuridad más allá del fuego.",
	["leans forward and pats their hands quickly against their knees, like feet on hard ground."] = "se inclina hacia delante y se da palmaditas rápidas en las rodillas, como pies sobre suelo duro.",
	["leans forward and works at an imaginary keyhole, tongue between their teeth."] = "se inclina hacia delante y trabaja en una cerradura imaginaria, con la lengua entre los dientes.",
	["leans forward slightly, then back, then forward again, listening each time."] = "se inclina un poco hacia delante, luego hacia atrás, luego otra vez hacia delante, escuchando cada vez.",
	["leans forward, pokes at something invisible with a stick, and sniffs thoughtfully."] = "se inclina hacia delante, hurga en algo invisible con un palo y olfatea con aire pensativo.",
	["leans forward, raises one hand, and waits, watching the ground."] = "se inclina hacia delante, levanta una mano y espera, mirando el suelo.",
	["leans hard to one side, arms braced, squinting into driving rain."] = "se inclina con fuerza hacia un lado, con los brazos tensos, entornando los ojos contra la lluvia.",
	["leans in and drops their voice, as if the captain might still overhear."] = "se inclina hacia delante y baja la voz, como si la capitana aún pudiera oírle.",
	["leans in close to the fire and lowers their voice."] = "se inclina hacia el fuego y baja la voz.",
	["leans in over the fire, so the light climbs their face, and lowers their voice."] = "se inclina sobre el fuego, de modo que la luz le sube por la cara, y baja la voz.",
	["leans lightly on an invisible pole, barely pressing."] = "se apoya levemente en una pértiga invisible, casi sin hacer fuerza.",
	["leans out with arms spread for balance, and glances down at a long drop."] = "se asoma con los brazos abiertos para no perder el equilibrio y mira hacia abajo, hacia una larga caída.",
	["leans over and brushes something away with one hand, then looks closer."] = "se inclina, aparta algo con una mano y luego mira más de cerca.",
	["leans over and lifts a stone with great care."] = "se inclina y levanta una piedra con muchísimo cuidado.",
	["leans over and runs a hand across the grass, then wipes it on their coat."] = "se inclina y pasa la mano por la hierba, y luego se la limpia en el abrigo.",
	["leans over to peer in the direction of {target}'s boots, then winces."] = "se inclina para echar un vistazo a las botas de {target}, y hace una mueca.",
	["leans sideways with arms outspread, one hand clutching an imaginary wrench."] = "se inclina hacia un lado con los brazos extendidos, aferrando una llave inglesa imaginaria.",
	["leans to one side and peers around something tall, then winces."] = "se inclina hacia un lado, se asoma por detrás de algo alto y hace una mueca.",
	["leans toward the fire, raises one finger, and tilts their head as though listening."] = "se inclina hacia el fuego, levanta un dedo y ladea la cabeza como si escuchara.",
	["leans toward the fire."] = "se inclina hacia el fuego.",
	["leans toward the firelight, as if about to share a secret."] = "se inclina hacia la luz del fuego, como quien va a contar un secreto.",
	["leans toward {target} with great seriousness, hands folded."] = "se inclina hacia {target} con muchísima seriedad, con las manos juntas.",
	["lets a long silence go by, watching the smoke above the flames."] = "deja pasar un largo silencio, mirando el humo sobre las llamas.",
	["lets go of the levers and raises both hands, grinning."] = "suelta las palancas y levanta las dos manos, sonriendo de oreja a oreja.",
	["lets go of their own sleeves and settles both hands in their lap."] = "se suelta las mangas y apoya las dos manos en el regazo.",
	["lets one hand hang low at their side, fingers moving as if scratching an ear."] = "deja una mano colgando a un costado, moviendo los dedos como si rascara una oreja.",
	["lets one hand hang low, palm open, and leaves it there."] = "baja una mano, con la palma abierta, y la deja ahí.",
	["lets the fire tick and settle for a while before going on."] = "deja que el fuego crepite y se asiente un rato antes de seguir.",
	["lets the silence sit a moment before saying anything else."] = "deja que el silencio se asiente un momento antes de decir nada más.",
	["lets the silence sit so long that a log settling in the fire sounds loud."] = "deja que el silencio se alargue tanto que un tronco al asentarse en el fuego suena fuerte.",
	["lets their eyes drift past the firelight into the dark, and keeps them there a little too long."] = "deja que la mirada se le pierda más allá del fuego, en la oscuridad, y la mantiene ahí un poco más de la cuenta.",
	["licks a fingertip, holds it up gravely, and nods as if it has told them something important."] = "se chupa la yema de un dedo, la levanta con gravedad y asiente como si el dedo le hubiera dicho algo importante.",
	["lifts a cup carefully in both hands, then sniffs it."] = "levanta con cuidado una copa con las dos manos, y luego la olfatea.",
	["lifts a hand in a small wave."] = "levanta la mano y saluda con un gesto pequeño.",
	["lifts a wet finger into the air, holds it there, and slowly lowers it."] = "alza un dedo mojado al aire, lo mantiene ahí y lo baja despacio.",
	["lifts an invisible cup, blows across it, and sips with great care."] = "levanta una taza invisible, sopla por encima y da un sorbo con mucho cuidado.",
	["lifts an invisible heavy sack to shoulder height and holds it there, waiting."] = "levanta un saco invisible y pesado hasta la altura del hombro y lo sostiene ahí, esperando.",
	["lifts an unseen plate and wipes it, very gently, with their sleeve."] = "levanta un plato invisible y lo limpia, con mucha delicadeza, con la manga.",
	["lifts one finger and gives a tiny invisible bell a single tap."] = "levanta un dedo y da un solo golpecito a una campanilla diminuta e invisible.",
	["lifts one fist and brings it down sharply, as if striking with a hammer of light."] = "levanta un puño y lo baja de golpe, como si golpeara con un martillo de luz.",
	["lifts one hand and studies the shadow it casts, turning it slowly."] = "levanta una mano y estudia la sombra que proyecta, girándola despacio.",
	["lifts one hand slowly, as if stepping over something, then lets it settle."] = "levanta una mano despacio, como si pasara por encima de algo, y luego la deja reposar.",
	["lifts the lid of an invisible box, very slowly."] = "levanta muy despacio la tapa de una caja invisible.",
	["lifts the stone to their ear and goes quiet."] = "se acerca la piedra al oído y se queda en silencio.",
	["lifts their chin and answers softly to no one, \"Here.\""] = "levanta la barbilla y responde en voz baja, a nadie: «Presente».",
	["lifts their chin and looks down their nose, cold as a winter morning."] = "alza la barbilla y mira por encima del hombro, con la frialdad de una mañana de invierno.",
	["lifts their chin and sniffs at the air, then wishes they hadn't."] = "levanta la barbilla y olfatea el aire, y enseguida se arrepiente.",
	["lifts their hand off the ground beside the fire, slowly, and listens."] = "levanta despacio la mano del suelo junto al fuego, y escucha.",
	["linen cloth"] = "paño de lino",
	["links their fingers together, then pulls hard with both arms."] = "entrelaza los dedos y luego tira con fuerza con ambos brazos.",
	["listens to the fire tick and pop, counting under their breath, then stops."] = "escucha cómo crepita y chasquea el fuego, contando entre dientes, y luego se detiene.",
	["looks above the firelight for a long, quiet moment."] = "se queda mirando más allá del resplandor del fuego un largo rato, en silencio.",
	["looks around at an unseen slope and gives a small, tired shrug."] = "pasea la vista por una ladera invisible y se encoge un poco de hombros, con cansancio.",
	["looks around the circle and lets the question hang, one eyebrow up."] = "recorre el círculo con la mirada y deja la pregunta en el aire, con una ceja levantada.",
	["looks around the circle and nods once at each listener, as if daring one of them to ask."] = "mira alrededor del corro y saluda con la cabeza una vez a cada oyente, como retando a cualquiera a preguntar.",
	["looks around the circle with raised eyebrows, waiting for someone to ask."] = "mira al corro con las cejas levantadas, esperando a que alguien pregunte.",
	["looks around the circle, daring someone to ask the obvious question."] = "recorre el círculo con la mirada, retando a alguien a hacer la pregunta obvia.",
	["looks at the ground near {target} and goes quiet."] = "mira el suelo cerca de {target} y se queda en silencio.",
	["looks at the log in their hand, and sets it down beside the fire instead of on it."] = "mira el leño que tiene en la mano, y lo deja junto al fuego en vez de echarlo dentro.",
	["looks at their empty hands, then follows something slow along the ground with their eyes."] = "se mira las manos vacías y luego sigue con la vista algo que avanza despacio por el suelo.",
	["looks at their hands, then slowly folds them out of sight."] = "se mira las manos y luego las esconde despacio.",
	["looks at their open hand for a moment, then closes it gently."] = "se mira la mano abierta un momento y luego la cierra con suavidad.",
	["looks at {target} across the flames for a little too long, then looks away."] = "mira a {target} por encima de las llamas un poco más de la cuenta y luego aparta la vista.",
	["looks at {target}, then back into the fire."] = "mira a {target} y luego vuelve a mirar el fuego.",
	["looks away and runs a thumb slowly along the edge of their sleeve."] = "aparta la mirada y pasa despacio un pulgar por el borde de la manga.",
	["looks down at the coals."] = "baja la mirada a las brasas.",
	["looks down at the fire, then at the ground beneath it, and nudges a stray coal back into the ring."] = "mira el fuego, luego el suelo bajo él, y devuelve al círculo una brasa que se había escapado.",
	["looks down at their boots, not sure how to go on."] = "se mira las botas, sin saber cómo seguir.",
	["looks down at their hands and slowly opens them."] = "se mira las manos y las abre despacio.",
	["looks down at their hands, working at an invisible length of rope."] = "se mira las manos, que trabajan un trozo de cuerda invisible.",
	["looks down at their own boot, and holds very still."] = "se mira la bota y se queda inmóvil.",
	["looks down at their own hands and turns them over slowly."] = "se mira las manos y les da la vuelta despacio.",
	["looks down at their wrist and gives it a small, testing shake."] = "se mira la muñeca y le da una pequeña sacudida de prueba.",
	["looks down fondly at a spot near their feet."] = "mira con cariño un punto junto a sus pies.",
	["looks down into their cup for a moment, smiling a little."] = "baja la vista a la taza un momento, con una pequeña sonrisa.",
	["looks down, startled, and slowly lowers one raised arm."] = "mira hacia abajo con un sobresalto y baja despacio un brazo que tenía levantado.",
	["looks from one side to the other, slowly, and then back again."] = "mira de un lado a otro, despacio, y luego vuelve a mirar.",
	["looks into the fire for a long moment, then nods once."] = "se queda mirando el fuego un buen rato y luego asiente una vez.",
	["looks into the fire."] = "mira el fuego.",
	["looks off into the dark beyond the circle, jaw tight."] = "mira hacia la oscuridad más allá del círculo, con la mandíbula apretada.",
	["looks off into the dark, as if counting distant campfires."] = "mira a lo lejos en la oscuridad, como si contara hogueras distantes.",
	["looks off into the distance, as if over still water, and goes quiet for a moment."] = "mira a lo lejos, como por encima de un agua quieta, y se queda en silencio un momento.",
	["looks out at some high, distant point and takes a slow breath."] = "contempla un punto alto y lejano y respira despacio.",
	["looks out over the heads of the circle, as if at a far-off valley."] = "mira por encima de las cabezas del corro, como hacia un valle lejano.",
	["looks past the firelight at the black trees, and very carefully does not answer them."] = "mira más allá de la lumbre, hacia los árboles negros, y con mucho cuidado no les contesta.",
	["looks skyward and slowly hunches their shoulders, as if something were circling."] = "mira al cielo y encoge poco a poco los hombros, como si algo volara en círculos.",
	["looks slowly around the circle, at each face the firelight reaches, and then away."] = "recorre despacio el círculo con la mirada, cada rostro que alcanza la luz del fuego, y luego la aparta.",
	["looks slowly around the circle, lips moving as if counting."] = "recorre el círculo despacio con la mirada, moviendo los labios como si contara.",
	["looks slowly down at their own hands, and draws them in close to the fire."] = "se mira las manos despacio y las acerca al fuego.",
	["looks slowly to either side, searching, then lowers their gaze."] = "mira despacio a un lado y a otro, buscando, y luego baja la mirada.",
	["looks slowly upward, then back down at the ground by their feet."] = "mira despacio hacia arriba y luego otra vez al suelo, a sus pies.",
	["looks up at the moon."] = "alza la vista hacia la luna.",
	["looks up at the sky."] = "alza la vista al cielo.",
	["looks up slowly, then down at their own feet, frowning."] = "levanta la vista despacio y luego se mira los pies, con el ceño fruncido.",
	["looks up toward the mountains."] = "alza la vista hacia las montañas.",
	["looks {target} up and down, counting something on their fingers."] = "mira a {target} de arriba abajo, contando algo con los dedos.",
	["lowers a bow and breathes out slowly."] = "baja un arco y suelta el aire despacio.",
	["lowers an invisible lantern slowly, then stops short and pulls it back."] = "baja despacio un farol invisible, se detiene en seco y lo retira.",
	["lowers the invisible spoon and shakes their head slowly."] = "baja el cucharón invisible y niega despacio con la cabeza.",
	["lowers their gaze and walks two fingers slowly along one knee, as if following something along the ground."] = "baja la mirada y hace caminar dos dedos despacio por una rodilla, como si siguiera un rastro por el suelo.",
	["lowers their head and rests both hands on their weapon."] = "agacha la cabeza y apoya ambas manos en el arma.",
	["lowers their head and sinks their shoulders slowly, like something going under."] = "baja la cabeza y hunde los hombros despacio, como algo que se va a pique.",
	["lowers their voice and glances over one shoulder at nobody."] = "baja la voz y mira por encima del hombro a nadie en particular.",
	["lowers their voice."] = "baja la voz.",
	["lunges forward and snaps one hand shut, then hauls it back."] = "se lanza hacia delante y cierra una mano de golpe, y luego tira de ella hacia atrás.",
	["makes a small gurgling noise, then looks embarrassed."] = "hace un pequeño gorgoteo y luego pone cara de apuro.",
	["makes a small, courteous bow, then another, then catches themselves halfway through a third."] = "hace una pequeña reverencia cortés, luego otra, y se detiene a mitad de una tercera.",
	["mimes a short, patient tap against the ground, over and over."] = "imita un golpecito corto y paciente contra el suelo, una y otra vez.",
	["mimes lifting the lid of a heavy chest, then lets their shoulders drop."] = "hace como que levanta la tapa de un cofre pesado y luego deja caer los hombros.",
	["mimes peeling something wet from their sleeve, with growing disgust."] = "hace como que se despega algo mojado de la manga, cada vez con más asco.",
	["mimes reaching down, lifting, and setting something gently on the ground."] = "hace como que se agacha, levanta algo y lo deja con cuidado en el suelo.",
	["mimes shaping a snowball between their palms and gives one short, hopeless throw."] = "hace como que aprieta una bola de nieve entre las palmas y la lanza sin ningún tino.",
	["mouths a word carefully and silently, as if practicing it."] = "articula una palabra con cuidado y en silencio, como si la estuviera ensayando.",
	["moves one hand as if brushing through hanging leaves."] = "mueve una mano como si apartara hojas colgantes.",
	["moves one hand forward, stops it suddenly, and waits with their head on one side."] = "mueve una mano hacia delante, la detiene de golpe y espera con la cabeza ladeada.",
	["moves their lips silently for a moment, eyes closed."] = "mueve los labios en silencio un momento, con los ojos cerrados.",
	["narrows their eyes and leans closer to something invisible, then draws back sharply."] = "entorna los ojos y se acerca a algo invisible, y luego se echa atrás de golpe.",
	["narrows their eyes and shifts their weight, as if sizing someone up."] = "entorna los ojos y cambia el peso de pie, como quien mide a un rival.",
	["narrows their eyes at {target}, then slowly grins."] = "entorna los ojos mirando a {target}, y poco a poco sonríe de oreja a oreja.",
	["narrows their eyes, as though at some small and hated foe."] = "entorna los ojos, como ante un enemigo pequeño y odiado.",
	["nods at the fire and shows their tusks in a wide, lazy grin."] = "señala el fuego con la barbilla y enseña los colmillos en una sonrisa ancha y perezosa.",
	["nods once, as if that's the end of the matter."] = "asiente una vez, como quien da el asunto por zanjado.",
	["nods slowly and approvingly, as if at a fine piece of work."] = "asiente despacio, con aprobación, como ante un trabajo bien hecho.",
	["nods solemnly at {target}."] = "asiente con solemnidad mirando a {target}.",
	["nods to {target} and settles back."] = "le hace un gesto con la cabeza a {target} y se acomoda.",
	["nudges a log deeper into the coals."] = "empuja un tronco más hondo entre las brasas.",
	["opens a pack, reaches in, and pulls their hand back quickly."] = "abre un morral, mete la mano y la saca de golpe.",
	["opens one hand and studies the middle of the palm in the firelight."] = "abre una mano y se estudia el centro de la palma a la luz del fuego.",
	["opens one hand slowly and looks at what would be lying in it."] = "abre una mano despacio y mira lo que habría en ella.",
	["opens one hand to reveal a small, dark seed, worn smooth with handling."] = "abre una mano y muestra una semilla pequeña y oscura, pulida de tanto manosearla.",
	["opens their mouth to answer, then thoughtfully closes it."] = "abre la boca para responder, y luego la cierra, pensándoselo mejor.",
	["opens their mouth to speak, then closes it and looks down at their hands."] = "abre la boca para hablar, luego la cierra y se mira las manos.",
	["passes something heavy from one hand to the other, again and again, quickly."] = "pasa algo pesado de una mano a la otra, una y otra vez, deprisa.",
	["pats a small pouch at their belt, and lets their hand stay there."] = "da unas palmaditas a una bolsita que lleva al cinto, y deja la mano ahí.",
	["pats an invisible pack at their side."] = "da unas palmadas a una bolsa invisible que lleva al costado.",
	["pats the air at shoulder height, as if feeling for something worn."] = "palpa el aire a la altura del hombro, como buscando algo desgastado.",
	["pats the empty ground beside them."] = "da unas palmaditas en el suelo vacío a su lado.",
	["pats the ground beside them as if greeting an old friend, nodding slowly."] = "da unas palmaditas en el suelo a su lado, como quien saluda a un viejo amigo, asintiendo despacio.",
	["pats their own face and arms, as if checking they're all still there."] = "se palpa la cara y los brazos, como para comprobar que todo sigue en su sitio.",
	["pats their pack gently."] = "da unas palmaditas suaves a su mochila.",
	["pats their pockets, then turns one inside out."] = "se palpa los bolsillos y luego le da la vuelta a uno.",
	["pats their stomach slowly with one hand, looking wounded."] = "se da palmaditas lentas en la barriga, con aire de dignidad herida.",
	["pats their stomach, then holds up one finger as though something has just occurred to them."] = "se da unas palmaditas en la barriga y levanta un dedo, como si acabara de caer en algo.",
	["pats their thigh twice, softly, and looks down."] = "se da dos palmaditas suaves en el muslo y baja la vista.",
	["pauses with an imaginary spoon halfway to their mouth."] = "se detiene con una cuchara imaginaria a medio camino de la boca.",
	["pauses with an invisible spoon halfway to their mouth, then slowly lowers it."] = "se detiene con una cuchara invisible a medio camino de la boca y luego la baja despacio.",
	["pauses, and raises a hand as if holding up a lantern."] = "se detiene y levanta una mano como si sostuviera un farol.",
	["peacebloom"] = "una flor de paz",
	["peels back a blanket and peers in, without any sudden movements."] = "levanta el borde de una manta y se asoma dentro, sin movimientos bruscos.",
	["peels something sticky off their sleeve, and then has trouble getting it off their fingers."] = "se despega algo pegajoso de la manga, y luego no hay manera de quitárselo de los dedos.",
	["peers at the ground near {target}, watching how the firelight falls."] = "observa el suelo cerca de {target}, fijándose en cómo cae la luz de la hoguera.",
	["peers between their fingers, as if through leaves, at something far off."] = "mira entre los dedos, como entre las hojas, algo que está muy lejos.",
	["peers down into cupped hands, searching for something small."] = "mira dentro de sus manos ahuecadas, buscando algo pequeño.",
	["peers into a bowl, then gives it a polite nod."] = "se asoma a un cuenco y luego le hace un educado gesto con la cabeza.",
	["peers off toward the hills, chewing slowly."] = "mira a lo lejos hacia las colinas, masticando despacio.",
	["peers over an imaginary edge and slowly draws back, swallowing."] = "se asoma a un borde imaginario y se retira despacio, tragando saliva.",
	["peers suspiciously into an imaginary bowl and stirs it with one finger."] = "mira con desconfianza dentro de un cuenco imaginario y lo remueve con un dedo.",
	["picks a twig from the kindling, considers how long it took to grow, and feeds it to the fire anyway."] = "coge una ramita de la leña, piensa en lo que tardó en crecer, y la echa al fuego de todos modos.",
	["picks an invisible crumb from their own chin, and studies it."] = "se quita una miga invisible de la barbilla y la examina.",
	["picks an invisible lock with two fingers, then freezes with their head cocked."] = "fuerza una cerradura invisible con dos dedos y se queda inmóvil, con la cabeza ladeada.",
	["picks at an invisible knot with blunt, patient fingers."] = "hurga en un nudo invisible con dedos gruesos y pacientes.",
	["picks at an invisible knot with their fingertips, frowning."] = "tira de un nudo invisible con la punta de los dedos, con el ceño fruncido.",
	["pinches an invisible line between two fingers and lets it droop slowly."] = "pellizca una cuerda invisible entre dos dedos y deja que se combe despacio.",
	["pinches an invisible needle and draws a slow thread through the air."] = "pellizca una aguja invisible y tira despacio de un hilo por el aire.",
	["pinches an invisible thread and lifts it carefully clear of something below."] = "pellizca un hilo invisible y lo levanta con cuidado por encima de algo.",
	["pitches forward with arms spread wide, then jerks upward as if yanked by the collar."] = "se inclina hacia delante con los brazos abiertos y luego da un respingo hacia arriba, como si le tiraran del cuello de la ropa.",
	["plants both hands flat on their knees and sets their shoulders, immovable."] = "apoya las dos manos en las rodillas y se planta, inamovible.",
	["plants their fists on their hips and glares at the ground, jaw thrust forward."] = "planta los puños en las caderas y fulmina el suelo con la mirada, adelantando la mandíbula.",
	["plants their hands on their hips and looks up, like someone addressing a stubborn child."] = "se pone en jarras y alza la vista, como quien riñe a un crío cabezota.",
	["plants their hands on their hips and surveys a vast and empty view."] = "se pone en jarras y contempla una vista inmensa y vacía.",
	["points around in a slow circle, lips moving silently."] = "señala a su alrededor en un círculo lento, moviendo los labios en silencio.",
	["points at two spots on their open palm, one and then the other."] = "señala dos puntos en la palma abierta de la mano, uno y luego el otro.",
	["points left with one hand, right with the other, and then tries to point up with an elbow."] = "señala a la izquierda con una mano, a la derecha con la otra, y luego intenta señalar hacia arriba con un codo.",
	["points left, then right, then gives their own hand a puzzled look."] = "señala a la izquierda, luego a la derecha, y luego se mira la mano con cara de desconcierto.",
	["points north with a stick from the fire."] = "señala al norte con un palo sacado del fuego.",
	["points once toward the fire ring, pauses, and lowers their hand without finishing the count."] = "señala una vez hacia las piedras que rodean la hoguera, se detiene y baja la mano sin terminar de contar.",
	["points slowly around the circle where they sit, at nothing in particular."] = "señala despacio a su alrededor, sin apuntar a nada en concreto.",
	["pokes a stick into the coals and considers it gravely."] = "hurga en las brasas con un palo y lo contempla con gravedad.",
	["pokes at the fire and watches the sparks climb."] = "atiza el fuego y mira cómo suben las chispas.",
	["pokes the fire and watches the sparks climb."] = "atiza el fuego y mira cómo suben las chispas.",
	["pokes the fire twice and clears their throat, a little too loudly."] = "atiza el fuego dos veces y carraspea, un poco demasiado fuerte.",
	["pokes the fire until it crackles, then looks around the circle."] = "atiza el fuego hasta que chisporrotea y luego recorre el corro con la mirada.",
	["pokes their tongue into their cheek and winces."] = "se empuja la mejilla con la lengua y hace una mueca de dolor.",
	["pops something imaginary into their mouth and chews happily."] = "se mete algo imaginario en la boca y mastica feliz.",
	["pounds out a rhythm on their thigh that falls apart almost at once."] = "aporrea un ritmo en el muslo que se desmorona casi al instante.",
	["presses a hand flat over their heart and lets out a long breath."] = "se lleva la mano abierta al corazón y suelta un largo suspiro.",
	["presses a palm flat against their chest, then lets it fall."] = "se aprieta la palma contra el pecho y luego deja caer la mano.",
	["presses an ear to an unseen pipe and holds their breath."] = "pega la oreja a un tubo invisible y contiene la respiración.",
	["presses one finger to their lips and looks up, not moving at all."] = "se lleva un dedo a los labios y mira hacia arriba, sin moverse lo más mínimo.",
	["presses one palm against the empty air and slowly draws it back."] = "apoya la palma de la mano contra el aire vacío y la retira despacio.",
	["presses one thumb gently into the center of their other palm."] = "aprieta suavemente un pulgar en el centro de la otra palma.",
	["presses their lips together and gives a small, stiff nod."] = "aprieta los labios y asiente con un gesto breve y rígido.",
	["presses their thumb into the palm of their other hand and holds it there."] = "se aprieta el pulgar contra la palma de la otra mano y lo mantiene ahí.",
	["pretends to gallop with both hands."] = "hace como que galopa con las dos manos.",
	["pretends to pour something from nothing."] = "hace como que sirve algo de la nada.",
	["prods a charred log with a stick, twice, just to be sure."] = "pincha un tronco chamuscado con un palo, dos veces, solo para asegurarse.",
	["puckers their mouth and swallows hard at the memory."] = "frunce los labios y traga saliva con fuerza al recordarlo.",
	["puffs out their cheeks and frowns up at the sky."] = "infla los carrillos y mira al cielo con el ceño fruncido.",
	["puffs out their chest proudly, then lets it sag."] = "saca pecho con orgullo y luego lo deja caer.",
	["puffs up their chest."] = "saca pecho.",
	["pulls a knot tight in an invisible rope, and keeps both hands on it."] = "aprieta un nudo en una cuerda invisible y no aparta las manos de ella.",
	["pulls a loose thread from their sleeve and drops it in the flames without a word."] = "se arranca un hilo suelto de la manga y lo deja caer a las llamas sin decir palabra.",
	["pulls a loose thread from their sleeve and lets the updraft off the fire carry it away."] = "tira de un hilo suelto de la manga y deja que la corriente que sube del fuego se lo lleve.",
	["pulls a small feather from nowhere and smooths it between their fingers."] = "saca una pluma pequeña de la nada y la alisa entre los dedos.",
	["pulls a worn spoon from their belt and gives it a little flourish."] = "saca una cuchara gastada del cinturón y la blande con una floritura.",
	["pulls an invisible folded letter from a pocket and frowns at it, then at {target}."] = "saca de un bolsillo una carta doblada invisible, la mira con el ceño fruncido y luego mira a {target}.",
	["pulls at something around their neck, and holds the end up to look at it."] = "tira de algo que lleva al cuello y levanta la punta para mirarla.",
	["pulls off an invisible coat, throws it over something, then tugs gently on a lead."] = "se quita un abrigo invisible, lo echa sobre algo y luego tira con suavidad de un ronzal.",
	["pulls on one invisible glove, then another over it, flexing their fingers."] = "se pone un guante invisible, luego otro encima, y flexiona los dedos.",
	["pulls slowly on an invisible rope, then again, keeping time."] = "tira despacio de una cuerda invisible, y otra vez, llevando el compás.",
	["pulls their coat closed and turns their face out of the firelight."] = "se cierra el abrigo y aparta la cara de la luz del fuego.",
	["pulls their hand back from the fire quickly."] = "aparta rápido la mano del fuego.",
	["pumps their arms, breathing hard, and glances back over one shoulder."] = "bracea con fuerza, jadeando, y echa un vistazo por encima del hombro.",
	["pumps their elbows where they sit, breathing hard."] = "mueve los codos como si corriera sin levantarse del sitio, jadeando.",
	["purses their lips and whistles two soft notes, up and down."] = "frunce los labios y silba dos notas suaves, arriba y abajo.",
	["pushes their pack an arm's length away, hesitates, and draws it close again."] = "aparta el morral a un brazo de distancia, duda y vuelve a acercárselo.",
	["raises a cup to no one in particular."] = "alza la taza hacia nadie en particular.",
	["raises a finger toward the dark overhead, then lets it sink."] = "levanta un dedo hacia la oscuridad de arriba y luego lo deja caer.",
	["raises a fist and brings it down slowly, as if on an unseen anvil."] = "alza un puño y lo baja despacio, como sobre un yunque invisible.",
	["raises a hand flat above their own head, as if measuring."] = "levanta una mano plana por encima de la cabeza, como si midiera algo.",
	["raises an eyebrow and gives the fire a slow, knowing look."] = "arquea una ceja y mira el fuego despacio, con complicidad.",
	["raises an imaginary mug toward the fire."] = "alza una jarra imaginaria hacia el fuego.",
	["raises an imaginary spear, sights down it, then shifts their aim a little low."] = "alza un arpón imaginario, apunta a lo largo del asta y luego baja un poco la puntería.",
	["raises an invisible bucket a little way, holds it there, and then sets it down again."] = "levanta un poco un cubo invisible, lo sostiene ahí, y luego lo vuelve a dejar en el suelo.",
	["raises an invisible vial to the firelight."] = "alza un vial invisible a la luz del fuego.",
	["raises an unsteady hand and sways where they sit, squinting along an invisible blade."] = "levanta una mano temblorosa y se tambalea en el sitio, mirando con los ojos entornados el filo de una espada invisible.",
	["raises both arms and sways solemnly from side to side."] = "levanta los dos brazos y se balancea solemnemente de un lado a otro.",
	["raises both fists and brings them down hard on an invisible drum, once, twice."] = "levanta los dos puños y los deja caer con fuerza sobre un tambor invisible, una vez, dos.",
	["raises both fists as if gripping a hilt and braces against the air."] = "levanta los dos puños como si empuñara una espada y se planta firme contra el aire.",
	["raises both hands as if gripping an axe, then brings them down hard."] = "alza las dos manos como si empuñara un hacha y las baja con fuerza.",
	["raises both hands solemnly, then winces at the memory."] = "alza ambas manos con solemnidad y luego hace una mueca al recordarlo.",
	["raises both palms, as if calming two arguing friends."] = "levanta las dos palmas, como quien calma a dos amigos que discuten.",
	["raises one arm overhead at an angle, bracing it with the other hand, and winces at each blow."] = "levanta un brazo en ángulo por encima de la cabeza, lo afianza con la otra mano y hace una mueca a cada golpe.",
	["raises one finger to explain, thinks better of it, and lowers it slowly."] = "levanta un dedo para explicarse, se lo piensa mejor y lo baja despacio.",
	["raises one hand near the fire and studies the shadow between their fingers."] = "acerca una mano al fuego y estudia la sombra que queda entre los dedos.",
	["raises one hand solemnly, as if casting a vote."] = "levanta una mano con solemnidad, como quien emite su voto.",
	["raises one open hand quickly, fingers spread, and holds it there."] = "levanta rápido una mano abierta, con los dedos separados, y la mantiene ahí.",
	["raises their cup, solemnly, as if to a worthy opponent."] = "alza la taza con solemnidad, como ante un rival digno.",
	["rakes the coals together with a stick, saving the heat."] = "junta las brasas con un palo, para guardar el calor.",
	["raps their knuckles three times on the ground, then waits."] = "da tres golpes con los nudillos en el suelo y espera.",
	["raps three times on the ground beside them, then waits, head tilted."] = "da tres golpes en el suelo a su lado y luego espera, con la cabeza ladeada.",
	["reaches out and gently smooths a strand of invisible hair."] = "alarga una mano y alisa con suavidad un mechón de pelo invisible.",
	["reaches up and carefully snips at something overhead with two fingers."] = "alza la mano y, con dos dedos, corta con cuidado algo por encima de su cabeza.",
	["reaches up, hand over hand, breathing harder with every reach."] = "va trepando con las manos, una tras otra, respirando cada vez más fuerte.",
	["rests a hand flat on their knee and looks into the coals for a while."] = "apoya la mano abierta sobre la rodilla y se queda un rato mirando las brasas.",
	["rests a hand on an invisible neck and pats it twice."] = "apoya una mano en un cuello invisible y le da dos palmaditas.",
	["rests one hand on the air, as if on the top of a low gate, then lets it fall."] = "apoya una mano en el aire, como sobre lo alto de una cancela baja, y luego la deja caer.",
	["rests their fingertips lightly over one pocket."] = "apoya con suavidad las yemas de los dedos sobre un bolsillo.",
	["rolls one shoulder, as if the bruise still aches."] = "mueve un hombro en círculo, como si aún le doliera el moratón.",
	["rolls something small between finger and thumb, then flicks it away."] = "hace rodar algo pequeño entre el índice y el pulgar, y luego lo lanza de un capirotazo.",
	["rolls their neck and stretches, in a distinctly animal way."] = "estira el cuello y se despereza, de una forma claramente animal.",
	["rolls their shoulders, then tilts slowly into some unfelt gust."] = "mueve los hombros y luego se inclina despacio hacia una ráfaga que nadie más siente.",
	["rolls up one sleeve to show an old, crescent-shaped scar."] = "se remanga un brazo y enseña una vieja cicatriz con forma de media luna.",
	["rubs a pinch of cold ash from the fire's edge between their fingers, and smiles."] = "frota entre los dedos una pizca de ceniza fría del borde del fuego, y sonríe.",
	["rubs a pinch of cold ash from the fire's edge between their fingers, with some satisfaction."] = "frota entre los dedos un pellizco de ceniza fría del borde de la hoguera, con cierta satisfacción.",
	["rubs a thumb across their own palm, as if the handshake were still there."] = "se pasa un pulgar por la palma de la mano, como si el apretón siguiera ahí.",
	["rubs a thumb across their palm, as if wiping dirt off something small."] = "se frota la palma con el pulgar, como si limpiara la tierra de algo pequeño.",
	["rubs a thumb and two fingers together."] = "se frota el pulgar contra dos dedos.",
	["rubs a thumb in small, firm circles over one palm."] = "frota un pulgar en círculos pequeños y firmes sobre una palma.",
	["rubs an invisible coin between finger and thumb."] = "frota una moneda invisible entre el índice y el pulgar.",
	["rubs both wrists slowly, as if feeling old chains."] = "se frota despacio las muñecas, como si aún notara unas cadenas viejas.",
	["rubs finger and thumb together as though testing a pinch of grit."] = "frota el índice y el pulgar como si probara una pizca de arena.",
	["rubs finger and thumb together, as though testing a pinch of soil."] = "se frota el índice y el pulgar, como quien prueba un pellizco de tierra.",
	["rubs the back of their neck, and looks down at the fire."] = "se frota la nuca y baja la vista al fuego.",
	["rubs the back of their neck, sheepish."] = "se rasca la nuca con cara de apuro.",
	["rubs the side of one thumb slowly across their palm."] = "frota despacio el costado de un pulgar contra la palma de la mano.",
	["rubs their fingers together, as if brushing away soot."] = "se frota los dedos, como si se sacudiera el hollín.",
	["rubs their hands together by the fire."] = "se frota las manos junto al fuego.",
	["rubs their thumb and fingers together as though testing for dust, then stops themselves."] = "se frota el pulgar contra los dedos como si buscara polvo, y luego se obliga a parar.",
	["runs a finger slowly down an invisible page, then stops."] = "recorre despacio con un dedo una página invisible y se detiene.",
	["runs a fingertip along an imaginary seam on their sleeve."] = "recorre con la yema del dedo una costura imaginaria de la manga.",
	["runs a hand low through the air, near the knee, as if along an old wall."] = "pasa una mano a poca altura por el aire, cerca de la rodilla, como si recorriera un muro viejo.",
	["runs a length of old cord through their fingers, stopping at each knot."] = "se pasa un trozo de cordel viejo entre los dedos y se detiene en cada nudo.",
	["runs a slow hand along an invisible length of wood, feeling for the grain."] = "pasa despacio la mano por una pieza invisible de madera, buscando la veta.",
	["runs a thumb along an invisible edge."] = "pasa el pulgar por un filo invisible.",
	["runs a thumb along an old notch in their weapon."] = "pasa el pulgar por una vieja muesca del arma.",
	["runs a thumb along the nicks in their blade."] = "pasa el pulgar por las mellas de la hoja.",
	["runs a thumb over a board, then stops at something and looks closer."] = "pasa un pulgar por un tablón, se detiene en algo y lo mira más de cerca.",
	["runs one finger down an invisible page, then stops."] = "recorre con un dedo una página invisible y luego se detiene.",
	["says nothing more, and watches the black branches lean a little closer over the firelight."] = "no dice nada más, y observa cómo las ramas negras se inclinan un poco más sobre la lumbre.",
	["scoops up a handful of dirt and lets it sift through their fingers."] = "coge un puñado de tierra y deja que se le escurra entre los dedos.",
	["scoops up a handful of imaginary dirt, frowns at it, and lets it run through their fingers."] = "coge un puñado de tierra imaginaria, la mira con el ceño fruncido y deja que se le escurra entre los dedos.",
	["scratches a slow line in the ashes with a stick, then adds another beneath it."] = "traza despacio una línea en la ceniza con un palo, y luego otra debajo.",
	["scratches an imaginary companion behind the ears."] = "rasca detrás de las orejas a un compañero imaginario.",
	["scuttles two fingers along an imaginary track, grinning wide."] = "hace correr dos dedos por una pista imaginaria, con una sonrisa de oreja a oreja.",
	["sets a scrap of jerky down beside them, where an old dog might find it."] = "deja un trozo de cecina a su lado, donde un perro viejo podría encontrarlo.",
	["sets a scrap of their dinner at the edge of the firelight, and does not look to see what comes."] = "deja un trozo de su cena al borde de la luz de la hoguera, y no mira qué viene a por él.",
	["sets a small stone on the ring around the fire, then a second beside it, and says no more."] = "pone una piedrecita en el círculo que rodea el fuego, luego otra al lado, y no dice nada más.",
	["sets one shoulder low and pushes slowly forward, jaw tight."] = "baja un hombro y empuja despacio hacia delante, con la mandíbula apretada.",
	["sets one thing on top of another, with great care, and sits back."] = "pone una cosa encima de otra, con muchísimo cuidado, y se echa hacia atrás.",
	["sets something down with both hands and does not look up."] = "deja algo en el suelo con ambas manos y no levanta la vista.",
	["sets something heavy down carefully and eases themselves back with a long breath."] = "deja algo pesado en el suelo con cuidado y se recuesta despacio, soltando un largo suspiro.",
	["sets the stick down and nods across the flames at {target}."] = "deja el palo y le hace un gesto con la cabeza a {target} por encima de las llamas.",
	["sets the stone by the ring of the fire, carefully, as if leaving it for someone."] = "deja la piedra junto al círculo de la hoguera, con cuidado, como si se la dejara a alguien.",
	["sets their two fists side by side, then opens a small gap between them."] = "pone los dos puños uno junto al otro y luego abre un pequeño hueco entre ellos.",
	["settles lower, as though easing onto the edge of a cot."] = "se encoge un poco, como quien se sienta despacio en el borde de un catre.",
	["settles their weight with a grunt and starts unlacing an imaginary boot with great care."] = "se acomoda con un gruñido y empieza a desatarse una bota imaginaria con mucho cuidado.",
	["shades their eyes and cranes their neck, squinting past the firelight."] = "se hace visera con la mano, estira el cuello y entorna los ojos para ver más allá de la lumbre.",
	["shades their eyes and peers around the circle of listeners, looking increasingly worried."] = "se hace visera con la mano y escudriña el corro de oyentes, con creciente preocupación.",
	["shades their eyes with one hand and peers around the fire."] = "se hace visera con una mano y escudriña alrededor del fuego.",
	["shakes a fist at the sky, then stops to catch their breath."] = "agita el puño hacia el cielo y luego se para a recuperar el aliento.",
	["shakes a fist in the air as if ringing a bell, faster and faster."] = "agita un puño en el aire como si tocara una campana, cada vez más rápido.",
	["shapes a small tin in the air with both hands, then gently closes the lid."] = "da forma a una latita en el aire con las dos manos y luego cierra la tapa con suavidad.",
	["shaves a thin curl from a small piece of wood and watches it fall."] = "saca una viruta fina de un trocito de madera y la mira caer.",
	["shields a tiny flame with one hand."] = "protege con una mano una llamita diminuta.",
	["shifts an invisible weight on one shoulder and rubs the spot with a grimace."] = "se recoloca un peso invisible en el hombro y se frota la zona con una mueca.",
	["shifts back against nothing at all and slowly, blissfully, rubs their back from side to side."] = "se recuesta contra la nada y, despacio y con cara de gusto, se frota la espalda de lado a lado.",
	["shifts over a little, leaving space by the fire as if for someone else."] = "se aparta un poco, dejando un hueco junto al fuego como si fuera para otra persona.",
	["shifts over to one side, leaving a space beside them."] = "se corre hacia un lado y deja un hueco libre a su lado.",
	["shivers and pulls their cloak a little tighter."] = "se estremece y se ciñe un poco más la capa.",
	["shoves at the air with both hands, wincing with each push."] = "empuja el aire con las dos manos, con una mueca a cada empujón.",
	["shoves both hands sideways through the air, hard."] = "da un fuerte empujón al aire con las dos manos, hacia un lado.",
	["shoves hard at the air with both hands."] = "empuja el aire con fuerza con ambas manos.",
	["shoves something round forward with both hands, then grips the air tight."] = "empuja algo redondo hacia delante con las dos manos y luego aprieta el aire con fuerza.",
	["sighs and shakes their head at the fire."] = "suspira y niega con la cabeza mirando al fuego.",
	["sighs."] = "suspira.",
	["sinks down slowly until their chin is tucked, eyes wide and darting."] = "se hunde despacio hasta esconder la barbilla, con los ojos muy abiertos y yendo de un lado a otro.",
	["sinks lower where they sit, with the long sigh of someone easing into a tub."] = "se hunde un poco más en el asiento, con el largo suspiro de quien se mete en una tina.",
	["sinks slowly downward with a look of deep calm, cheeks not puffed at all."] = "se hunde despacio con una expresión de profunda calma, sin hinchar los carrillos en absoluto.",
	["sits back from the fire and lets the story settle."] = "se aparta un poco del fuego y deja que la historia se asiente.",
	["sits perfectly still, one arm still raised from the throw."] = "se queda inmóvil del todo, con un brazo todavía en alto tras el lanzamiento.",
	["sits up straight and raises one hand, palm out, like someone refusing a request."] = "se endereza y levanta una mano con la palma hacia fuera, como quien rechaza una petición.",
	["sits up suddenly and listens, one hand raised for silence."] = "se incorpora de golpe y escucha, con una mano en alto pidiendo silencio.",
	["sits up very slowly, arms stiff at their sides, staring ahead."] = "se incorpora muy despacio, con los brazos rígidos pegados al cuerpo y la mirada al frente.",
	["sits up very straight, eyes fixed on something far past the firelight."] = "endereza la espalda, con la mirada fija en algo muy lejos del resplandor del fuego.",
	["sits up very straight, folds their arms, and closes their eyes."] = "endereza la espalda, se cruza de brazos y cierra los ojos.",
	["sits up with their chin level and shoulders still, as if a brimming bowl rested on their head."] = "endereza la espalda, con la barbilla recta y los hombros quietos, como si llevara en la cabeza un cuenco a rebosar.",
	["sits very still, the firelight moving over a face that does not."] = "permanece inmóvil; la luz del fuego baila sobre un rostro que ni se inmuta.",
	["sketches a huge curve in the air with one finger."] = "dibuja en el aire una curva enorme con un dedo.",
	["sketches a weary sign of blessing in the air, like someone swatting a fly."] = "traza en el aire una señal de bendición muy cansada, como quien espanta una mosca.",
	["slaps at their neck, then their arm, then flails at the empty air."] = "se da un manotazo en el cuello, luego en el brazo, y luego manotea contra el aire.",
	["slashes left, slashes right, then throws an arm up against an imaginary blow."] = "da un tajo a la izquierda, otro a la derecha, y luego alza un brazo contra un golpe imaginario.",
	["slides half of an invisible stack of coins toward themselves, leaving the rest."] = "desliza hacia sí la mitad de un montón invisible de monedas y deja el resto.",
	["slides three invisible cups around on the ground, fast."] = "mueve tres cubiletes invisibles por el suelo, muy rápido.",
	["slowly lowers their hands and wipes them on their knees."] = "baja las manos despacio y se las limpia en las rodillas.",
	["slowly raises their eyes upward, then lowers them again."] = "alza la mirada muy despacio y luego la vuelve a bajar.",
	["slowly tips their shoulders to the wrong side and holds there, looking uneasy."] = "inclina despacio los hombros hacia el lado equivocado y se mantiene así, con cara de inquietud.",
	["slumps sideways with their tongue out and eyes rolled up, perfectly still."] = "se desploma de lado con la lengua fuera y los ojos en blanco, sin mover un músculo.",
	["smiles a little into their cup and lets the joke stand."] = "sonríe un poco a la taza y deja el chiste ahí.",
	["smiles and lays a hand flat over their heart."] = "sonríe y se pone la mano abierta sobre el corazón.",
	["smiles at the fire."] = "le sonríe al fuego.",
	["smiles at {target} a little too brightly."] = "le sonríe a {target} con demasiado entusiasmo.",
	["smiles down at a folded scrap of paper they clearly cannot read."] = "sonríe mirando un papel doblado que, salta a la vista, no sabe leer.",
	["smiles into the fire, and doesn't say anything for a moment."] = "sonríe mirando al fuego y se queda un momento sin decir nada.",
	["smiles into the fire."] = "le sonríe al fuego.",
	["smiles thinly and looks away, shifting so the firelight doesn't quite reach their face."] = "sonríe apenas y aparta la mirada, moviéndose para que la luz del fuego no le llegue del todo a la cara.",
	["smiles to themselves."] = "sonríe para sus adentros.",
	["smooths a fold of cloth across one knee, slowly, and leaves their hand resting on it."] = "alisa despacio un pliegue de tela sobre la rodilla y deja la mano apoyada encima.",
	["smooths a patch of ground flat with the palm of one hand."] = "alisa un trozo de suelo con la palma de la mano.",
	["smooths down the front of their shirt with a small, pleased smile."] = "se alisa la pechera de la camisa con una sonrisita satisfecha.",
	["smooths down their hair, looking faintly worried."] = "se alisa el pelo, con cierta cara de preocupación.",
	["snaps a thorny branch for the fire, sucks a pricked thumb, and nods as if the point were proved."] = "parte una rama espinosa para el fuego, se chupa el pulgar pinchado y asiente, como si quedara demostrado.",
	["snaps their fingers, looks pleased, and then lets the smile slowly fade."] = "chasquea los dedos con cara de satisfacción, y luego deja que la sonrisa se le borre despacio.",
	["snatches at something on the ground, then hunches low with an arm over their head."] = "arrebata algo del suelo y luego se agacha, cubriéndose la cabeza con el brazo.",
	["snatches up a stick and scrawls furiously in the ashes, as if it were a stub of chalk."] = "agarra un palo y garabatea furiosamente en la ceniza, como si fuera un cabo de tiza.",
	["sneezes enormously, then looks around in horror."] = "suelta un estornudo descomunal y luego mira a su alrededor con horror.",
	["sniffs one wrist, winces, and wipes it on their knee."] = "se huele una muñeca, hace una mueca y se la limpia en la rodilla.",
	["sniffs the air once, then stops, and presses their lips together."] = "olfatea el aire una vez, luego para, y aprieta los labios.",
	["sniffs the air, then slowly turns their head to look behind them."] = "olfatea el aire y luego gira despacio la cabeza para mirar atrás.",
	["spreads both hands, palms up, and lifts them slowly."] = "abre las dos manos, con las palmas hacia arriba, y las alza despacio.",
	["spreads their arms wide and hisses, then looks faintly embarrassed."] = "abre los brazos de par en par y sisea, y luego se le nota un poco la vergüenza.",
	["spreads their arms wide and wobbles, trying to keep their balance."] = "abre mucho los brazos y se tambalea, intentando no perder el equilibrio.",
	["spreads their hands in a gesture of complete and final innocence."] = "extiende las manos en un gesto de inocencia total y definitiva.",
	["spreads their hands wider and wider apart, as if measuring a raptor that keeps growing."] = "separa las manos cada vez más, como si midiera a un raptor que no para de crecer.",
	["spreads their hands wider and wider, then slowly draws them back into their lap."] = "separa las manos cada vez más, y luego las devuelve despacio al regazo.",
	["spreads their hands, still honestly troubled by the question."] = "abre las manos; la pregunta todavía le inquieta de verdad.",
	["squares their shoulders and raises one arm, as if a shield still hung from it."] = "cuadra los hombros y levanta un brazo, como si aún cargara con un escudo.",
	["squints across the fire at {target}, tilting their head one way and then the other."] = "entorna los ojos mirando a {target} al otro lado del fuego, y ladea la cabeza primero a un lado y luego al otro.",
	["squints along the rim of an invisible mug, deeply unconvinced."] = "mira el borde de una jarra invisible con los ojos entornados, sin creérselo en absoluto.",
	["squints and rubs their temples with both hands."] = "entorna los ojos y se frota las sienes con las dos manos.",
	["squints at the coals with a smith's eye, plainly unimpressed, then grins."] = "mira las brasas con ojo de herrero, sin que le convenzan lo más mínimo, y luego sonríe.",
	["stares at nothing in particular for a while before speaking."] = "se queda mirando a la nada un rato antes de hablar.",
	["stares blankly ahead, imitating a whole room of unamused faces."] = "mira al frente sin expresión, imitando una sala entera de caras serias.",
	["stares down at an invisible bowl, a spoon halfway to their mouth."] = "mira fijamente un cuenco invisible, con la cuchara a medio camino de la boca.",
	["stares hard into the dark beyond the fire, without blinking."] = "mira fijamente la oscuridad más allá del fuego, sin parpadear.",
	["stares into the coals for a long moment."] = "se queda mirando las brasas un buen rato.",
	["stares into the fire a while before looking up again."] = "se queda un rato mirando el fuego antes de volver a alzar la vista.",
	["stares into the fire, as if it might have an answer of its own."] = "mira fijamente el fuego, como si pudiera tener una respuesta propia.",
	["stares into the flames and doesn't blink for a while."] = "mira fijamente las llamas y no parpadea en un buen rato.",
	["stares into the sullen, smoking fire, and takes their time before going on."] = "mira fijamente el fuego, hosco y humeante, y se toma su tiempo antes de seguir.",
	["stays very still, head cocked toward the dark, as though for two soft notes."] = "permanece inmóvil, con la cabeza ladeada hacia la oscuridad, como si esperara dos notas suaves.",
	["steps their hands forward through the air, one flat palm after the other, testing each one."] = "va adelantando las manos por el aire, primero una palma y luego la otra, tanteando cada paso.",
	["stirs an invisible pot with growing effort, then stops, the spoon stuck fast."] = "remueve una olla invisible cada vez con más esfuerzo, y se detiene con la cuchara atascada.",
	["stirs the coals with a stick, lips still moving."] = "remueve las brasas con un palo, moviendo todavía los labios.",
	["stops fiddling with a small gear and just holds it."] = "deja de juguetear con un engranaje pequeño y se limita a sostenerlo.",
	["stops moving entirely, barely breathing, eyes fixed on the dark."] = "deja de moverse por completo, sin apenas respirar, con los ojos clavados en la oscuridad.",
	["stops talking and holds very still for a moment."] = "se calla y, por un momento, no mueve ni un músculo.",
	["stops talking and looks just past {target}'s shoulder."] = "deja de hablar y mira justo por encima del hombro de {target}.",
	["straightens their back, chin high, one hand flat over the heart."] = "endereza la espalda, con la barbilla alta y una mano abierta sobre el corazón.",
	["straightens their collar and attempts an expression of great respectability."] = "se endereza el cuello e intenta poner cara de persona muy respetable.",
	["straightens their own collar, then straightens it again, more carefully."] = "se endereza el cuello de la ropa, y luego otra vez, con más cuidado.",
	["stretches and settles back, ready for sleep."] = "se despereza y se acomoda para dormir.",
	["stretches their hands toward a fire, then slowly draws them back."] = "extiende las manos hacia un fuego y luego las retira despacio.",
	["stretches their mouth into a stiff, uncertain grin, then lets it drop."] = "estira la boca en una sonrisa rígida y dudosa, y luego la deja caer.",
	["stretches their shoulders and lets out a slow, contented breath."] = "estira los hombros y suelta un suspiro lento y satisfecho.",
	["strikes their hands together sharply, then shields their eyes from a sudden blaze."] = "da una palmada seca y luego se protege los ojos de un fogonazo repentino.",
	["studies {target} across the fire with a thoughtful frown."] = "estudia a {target} al otro lado del fuego, con el ceño fruncido y aire pensativo.",
	["sways a little where they sit, as if to slow music."] = "se mece un poco sin levantarse, como al son de una música lenta.",
	["sways gently where they sit, wearing a look of perfect trust."] = "se balancea suavemente en su sitio, con cara de confianza absoluta.",
	["swings an arm wildly at nothing, falling just short, then lets it drop."] = "lanza un brazo con furia contra la nada, se queda a un palmo y lo deja caer.",
	["swings an imaginary pick, slowly, then rubs the small of their back with a groan."] = "balancea un pico imaginario, despacio, y luego se frota los riñones con un gruñido.",
	["swings an invisible tool down onto the ground."] = "descarga una herramienta invisible contra el suelo.",
	["swings one arm in a wide loop over their head and lets something fly."] = "hace girar un brazo en un amplio círculo por encima de la cabeza y suelta algo.",
	["takes a bite of the apple, chews, and pitches the core into the fire, where it hisses."] = "le da un mordisco a la manzana, mastica y tira el corazón al fuego, donde sisea.",
	["takes a sip from their cup and makes a sour face."] = "da un sorbo de la taza y tuerce el gesto.",
	["takes a split log from the firewood, knocks twice on it, and listens to the sound."] = "coge un leño partido del montón, le da dos golpes y escucha cómo suena.",
	["takes a worn, much-folded letter from a pouch and smooths it out."] = "saca de una bolsita una carta gastada, doblada mil veces, y la alisa.",
	["takes off one boot, turns it over, and watches a thin stream of sand patter into the fire."] = "se quita una bota, le da la vuelta y mira cómo cae un hilillo de arena en el fuego.",
	["takes out a small stoppered jar and tilts it toward the light."] = "saca un tarrito con tapón y lo inclina hacia la luz.",
	["takes something small from a pocket, looks at it, and puts it carefully away again."] = "saca algo pequeño de un bolsillo, lo mira y lo vuelve a guardar con cuidado.",
	["taps a finger against their chin."] = "se da golpecitos en la barbilla con un dedo.",
	["taps a fingernail once against the rim of a cup, then listens."] = "da un golpecito con la uña en el borde de una taza y se queda escuchando.",
	["taps a knuckle gently against an invisible stone, and tilts their head as if listening."] = "da unos golpecitos suaves con un nudillo sobre una piedra invisible e inclina la cabeza como si escuchara.",
	["taps a slow rhythm on their own knee with both hands, eyes closed."] = "marca un ritmo lento sobre la rodilla con ambas manos, con los ojos cerrados.",
	["taps a small imaginary gavel, then flinches at the sound."] = "da unos golpecitos con un mazo imaginario y se sobresalta con el ruido.",
	["taps one knuckle against a piece of firewood and listens."] = "da unos golpecitos con un nudillo en un leño y escucha.",
	["taps out a slow rhythm with one finger: long, short, short."] = "marca un ritmo lento con un dedo: largo, corto, corto.",
	["taps the side of their cup to get everyone's attention."] = "da unos golpecitos a la taza para que todos le presten atención.",
	["taps the side of their cup, slow and even, like someone counting."] = "da golpecitos en un lado de la taza, lentos y regulares, como quien lleva la cuenta.",
	["taps the side of their nose twice."] = "se da dos golpecitos en un lado de la nariz.",
	["taps their chin, thinking, then spreads their hands helplessly."] = "se da golpecitos en la barbilla, pensando, y luego abre las manos sin saber qué decir.",
	["taps twice on something unseen, then quickly pulls their hand away."] = "da dos golpecitos sobre algo invisible y aparta la mano enseguida.",
	["taps two fingers against their chest, where a badge might have hung."] = "se da dos golpecitos en el pecho, donde antes podría haber colgado una insignia.",
	["taps two fingers slowly against their temple."] = "se da unos golpecitos lentos en la sien con dos dedos.",
	["tears a piece of bread in two, looking at it thoughtfully."] = "parte un trozo de pan en dos y lo mira con aire pensativo.",
	["tears an invisible strip of meat in two and offers half across a fire."] = "parte en dos una tira de carne invisible y ofrece la mitad por encima del fuego.",
	["tests a knot with both hands, then tests it again."] = "prueba un nudo con las dos manos, y luego lo vuelve a probar.",
	["the first thing you'll mine when you're new to the town. What am I?"] = "lo primero que picas cuando aún no tienes galones. ¿Qué soy?",
	["the gold, and then I'll carry you over the ground. What am I?"] = "y después ya te llevo yo de un lado para otro lado. ¿Qué soy?",
	["the whole city asks if they've heard about you. What am I?"] = "toda la ciudad pregunta si alguien me ha nombrado. ¿Qué soy?",
	["then rise with my help on a borrowed breath. What am I?"] = "y gracias a mí se levanta con aliento prestado. ¿Qué soy?",
	["throws both arms out as if skidding to a stop, and stares down in horror."] = "abre los brazos de golpe como si frenara en seco, y mira hacia abajo con horror.",
	["throws both arms up as if in front of a roaring crowd."] = "levanta los dos brazos como ante un público enfervorizado.",
	["throws one arm over their face and leans hard into nothing, gritting their teeth."] = "se tapa la cara con un brazo y se inclina con fuerza contra la nada, apretando los dientes.",
	["throws themselves sideways with a great splash of both hands."] = "se tira de lado y salpica a lo grande con las dos manos.",
	["throws up their hands and laughs at the fire."] = "levanta las manos al cielo y se ríe mirando al fuego.",
	["thumps a fist against their own chest and listens to the sound."] = "se da un puñetazo en el pecho y escucha cómo suena.",
	["ties a neat knot in a bit of string without looking, then pulls it loose."] = "hace un nudo limpio en un trozo de cordel sin mirar, y luego lo suelta de un tirón.",
	["ties the knot again, and this time leaves it tied."] = "vuelve a hacer el nudo, y esta vez lo deja atado.",
	["tilts an invisible cup slowly sideways and watches it with great suspicion."] = "inclina despacio una taza invisible hacia un lado y la observa con mucha desconfianza.",
	["tilts slowly to one side, holds it for a moment, then straightens with a sigh."] = "se inclina despacio hacia un lado, aguanta un momento y luego se endereza con un suspiro.",
	["tilts their face to the sky with their eyes closed and their palms up."] = "alza la cara al cielo con los ojos cerrados y las palmas hacia arriba.",
	["tilts their head and leans it against the empty air, as though resting one ear on something huge."] = "ladea la cabeza y la apoya en el aire vacío, como si descansara una oreja sobre algo enorme.",
	["tilts their head back and stares at the sky."] = "echa la cabeza hacia atrás y se queda mirando el cielo.",
	["tilts their head back, as though looking up into tall branches."] = "echa la cabeza hacia atrás, como si mirara unas ramas muy altas.",
	["tilts their head sideways and clears their throat with exaggerated courtesy."] = "ladea la cabeza y carraspea con una cortesía exagerada.",
	["tilts their head sideways and tugs gently at nothing, with growing concern."] = "ladea la cabeza y tira con suavidad de la nada, con una inquietud creciente.",
	["tilts their head slightly, as though hearing something faint."] = "ladea un poco la cabeza, como si oyera algo muy débil.",
	["tilts their head toward the dark and attempts an innocent expression."] = "ladea la cabeza hacia la oscuridad e intenta poner cara de no haber roto nunca un plato.",
	["tilts their head toward the ground and listens, not moving at all."] = "inclina la cabeza hacia el suelo y escucha, sin moverse lo más mínimo.",
	["tilts their head, as though listening for rain on a roof far from here."] = "ladea la cabeza, como si escuchara la lluvia sobre un tejado muy lejos de aquí.",
	["tilts their head, listening, and holds up one finger for silence."] = "ladea la cabeza, escuchando, y levanta un dedo para pedir silencio.",
	["tilts their head, wearing a look of gentle confusion."] = "ladea la cabeza, con cara de suave desconcierto.",
	["tips a little from their waterskin onto the ground beside them, and says nothing more."] = "vierte un poco del odre en el suelo, a su lado, y no dice nada más.",
	["tips an imaginary hat toward the darkness."] = "se toca un sombrero imaginario a modo de saludo hacia la oscuridad.",
	["tips their head back and goes quiet, gazing straight up."] = "echa la cabeza atrás y se queda en silencio, mirando hacia arriba.",
	["tosses a dry twig into the flames and watches how quickly it is gone."] = "echa una ramita seca a las llamas y mira lo deprisa que desaparece.",
	["tosses a small bone into the fire with great bitterness."] = "echa un huesecillo al fuego con mucho rencor.",
	["tosses an apple up and catches it without looking."] = "lanza una manzana al aire y la coge sin mirar.",
	["touches one finger to an imaginary jug and frosts it with tremendous solemnity."] = "toca con un dedo una jarra imaginaria y la escarcha con una solemnidad tremenda.",
	["touches their rolled bedding, then draws their hands back toward the warmth."] = "toca el petate enrollado y luego vuelve a acercar las manos al calor.",
	["touches two fingers to the ground, then to their heart."] = "toca el suelo con dos dedos y luego se los lleva al corazón.",
	["traces a few letters in the dirt with one finger, then wipes them away."] = "traza unas letras en la tierra con un dedo y luego las borra.",
	["traces a few slow letters in the air with one finger."] = "traza unas cuantas letras lentas en el aire con un dedo.",
	["traces a line across an invisible page, lips moving silently."] = "recorre con el dedo una línea de una página invisible, moviendo los labios en silencio.",
	["traces a line across their palm with one finger, then taps it with a knuckle."] = "traza una línea en la palma de la mano con un dedo y luego le da un golpecito con el nudillo.",
	["traces a little patch shape in the air and goes still."] = "dibuja en el aire la forma de un pequeño remiendo y ya no se mueve.",
	["traces a long, winding shape across the sky with one finger."] = "traza con un dedo una forma larga y sinuosa en el cielo.",
	["tucks something small into an invisible crack, glancing left and right."] = "mete algo pequeño en una grieta invisible, mirando a izquierda y derecha.",
	["tucks the cord away and looks out past the firelight."] = "guarda el cordel y mira más allá de la luz del fuego.",
	["tucks the folded paper into a pocket, close to their heart."] = "se guarda el papel doblado en un bolsillo, cerca del corazón.",
	["tucks the invisible button into a pocket and pats it."] = "se guarda el botón invisible en un bolsillo y le da unas palmaditas.",
	["tucks the jar away again, gently, and pats the pocket twice."] = "vuelve a guardar el tarro, con cuidado, y da dos palmaditas en el bolsillo.",
	["tucks their elbows in tight and works both hands in a small space, feeling for something."] = "pega los codos al cuerpo y mueve las dos manos en un espacio estrecho, buscando algo a tientas.",
	["tugs at a lead rope, then lets it go slack."] = "tira de una cuerda y luego la deja floja.",
	["tugs at their sleeve and checks the stitching, as if for the hundredth time."] = "se tira de la manga y revisa la costura, como por centésima vez.",
	["turns a cup slowly in their hands, not drinking."] = "hace girar despacio una taza entre las manos, sin beber.",
	["turns a flat stone over in their fingers, as if looking for water to skip it on."] = "le da vueltas a una piedra plana entre los dedos, como si buscara agua donde hacerla rebotar.",
	["turns a folded paper over in their hands without opening it."] = "le da vueltas entre las manos a un papel doblado, sin abrirlo.",
	["turns a pebble over and sets it down without a sound."] = "le da la vuelta a un guijarro y lo deja en el suelo sin hacer ruido.",
	["turns a small stone in their fingers, looking over at {target}."] = "le da vueltas a una piedrecita entre los dedos, mirando a {target}.",
	["turns a small, invisible package over in their hands."] = "le da vueltas entre las manos a un paquetito invisible.",
	["turns a smooth gray pebble over in their fingers."] = "le da vueltas entre los dedos a un guijarro gris y liso.",
	["turns a stick over in the coals and does not look up."] = "da la vuelta a un palo entre las brasas y no levanta la vista.",
	["turns an invisible knot over in their fingers, slowly, examining it."] = "da vueltas a un nudo invisible entre los dedos, despacio, examinándolo.",
	["turns an invisible page, slowly, and runs a finger down it."] = "pasa despacio una página invisible y la recorre con el dedo.",
	["turns an invisible page, slowly, then stops and does not turn the next one."] = "pasa despacio una página invisible, se detiene y no pasa la siguiente.",
	["turns invisible pages, slowly, one at a time."] = "pasa páginas invisibles, despacio, una a una.",
	["turns one hand over slowly, as if holding something small and bright."] = "gira despacio una mano, como si sostuviera algo pequeño y brillante.",
	["turns one hand over slowly, palm down, and lays it flat."] = "gira una mano despacio, con la palma hacia abajo, y la apoya plana.",
	["turns one hand palm up, then palm down, and stares at it."] = "gira una mano con la palma hacia arriba, luego hacia abajo, y se la queda mirando.",
	["turns one open hand toward the other, leaving a little space between them."] = "vuelve una mano abierta hacia la otra, dejando un pequeño espacio entre ellas.",
	["turns one palm over and studies it for a while."] = "gira una mano con la palma hacia arriba y se la queda mirando un rato.",
	["turns one palm upward as though weighing a leaf, then closes their fingers."] = "pone una palma hacia arriba como si sopesara una hoja, y luego cierra los dedos.",
	["turns out one empty pocket, then the other, and sighs."] = "saca un bolsillo vacío del revés, luego el otro, y suspira.",
	["turns over something small on the ground with one finger, and watches it crawl away."] = "le da la vuelta con un dedo a algo pequeño en el suelo, y lo ve alejarse correteando.",
	["turns partway from the fire, then stops and glances back over one shoulder into the dark."] = "se aparta un poco del fuego, se detiene y mira por encima del hombro hacia la oscuridad.",
	["turns the blade so the firelight slides along its edge, and looks at it for a while."] = "gira la hoja para que la luz del fuego resbale por el filo, y se la queda mirando un rato.",
	["turns the invisible letter around and holds it out so the writing faces {target}."] = "da la vuelta a la carta invisible y se la enseña a {target}, con la letra por delante.",
	["turns the wood to the firelight, then takes off another curl and flicks it into the flames."] = "gira la madera hacia la luz del fuego, saca otra viruta y la tira a las llamas de un capirotazo.",
	["turns their face away and hunches their shoulders against a blast of wind."] = "aparta la cara y encoge los hombros contra un golpe de viento.",
	["turns their face beyond the firelight and pauses as though an answer is still owed."] = "vuelve la cara hacia la oscuridad, más allá de la lumbre, y se detiene, como si aún debiera una respuesta.",
	["turns their face up, as if into a strong wind, and speaks a few silent words."] = "alza la cara, como hacia un viento fuerte, y pronuncia unas palabras sin voz.",
	["turns their head by slow degrees until they're looking over one shoulder."] = "gira la cabeza poco a poco hasta mirar por encima del hombro.",
	["turns their head to the side and stares with one unblinking eye."] = "gira la cabeza de lado y mira fijamente con un ojo que no parpadea.",
	["turns their head toward the empty air beside them, and holds very still."] = "gira la cabeza hacia el aire vacío que tiene al lado, y no mueve ni un músculo.",
	["turns to {target} and opens one hand, palm up."] = "se vuelve hacia {target} y abre una mano, con la palma hacia arriba.",
	["turns to {target}, speaking more softly now."] = "se vuelve hacia {target}, hablando ahora más bajo.",
	["twirls one finger in a tight little circle, then points sharply."] = "hace girar un dedo en un circulito muy cerrado y luego señala de golpe.",
	["twists an invisible handful of grass together and ties it off with care."] = "retuerce un puñado invisible de hierba y lo anuda con cuidado.",
	["twists one fist slowly, as if turning a stiff post in the ground."] = "gira un puño despacio, como si hiciera girar un poste bien clavado en el suelo.",
	["twists their whole body and yanks hard on a strap."] = "retuerce todo el cuerpo y tira con fuerza de una correa.",
	["twitches their nose and jerks their head around, wide-eyed, at nothing."] = "arruga la nariz y gira la cabeza de golpe, con los ojos como platos, pero no hay nada.",
	["unfolds a scrap of paper and holds it up for all to admire."] = "despliega un trozo de papel y lo levanta para que todos lo admiren.",
	["unfolds an invisible stool with great pride and pats the top of it."] = "despliega un taburete invisible con muchísimo orgullo y le da unas palmaditas en el asiento.",
	["unrolls a map and smooths it flat with both hands."] = "despliega un mapa y lo alisa con las dos manos.",
	["wags a finger across the fire at {target}."] = "agita un dedo en dirección a {target}, al otro lado del fuego.",
	["waits while a log settles in the fire with a low thud, and does not seem to like the sound."] = "espera mientras un tronco se asienta en el fuego con un golpe sordo, y no parece gustarle nada el ruido.",
	["walks two fingers briskly off the edge of one knee, then winces all the way down."] = "baja dos dedos a paso vivo por el borde de una rodilla y hace una mueca durante toda la caída.",
	["watches a log settle in the fire and does not look up for a moment."] = "mira cómo se asienta un tronco en el fuego y tarda un momento en levantar la vista.",
	["watches a log settle in the fire and does not speak again."] = "mira cómo se asienta un tronco en el fuego y no vuelve a hablar.",
	["watches a slow ripple of heat cross the coals, and lets it fade."] = "observa cómo una onda lenta de calor cruza las brasas, y la deja apagarse.",
	["watches one spark circle up above the flames, around and around, until it winks out."] = "observa una chispa que sube sobre las llamas, dando vueltas y vueltas, hasta que se apaga.",
	["watches something roll slowly past, following it with one pointing finger."] = "mira algo que pasa rodando despacio y lo sigue con un dedo.",
	["watches the fire for a while, the way one might watch a lit window from outside."] = "mira el fuego un rato, como quien mira desde fuera una ventana iluminada.",
	["watches the smoke climb as it might from a chimney, and is the first to look away."] = "mira subir el humo como si saliera de una chimenea, y aparta la vista antes que nadie.",
	["watches the smoke drift off into the dark for a long while."] = "mira largo rato cómo el humo se pierde en la oscuridad.",
	["watches the smoke drift toward the listeners, scowls, and waves it back."] = "ve cómo el humo va hacia los oyentes, frunce el ceño y lo aparta con la mano.",
	["watches the smoke lean one way, then the other, and nods as if it had spoken."] = "observa cómo el humo se inclina hacia un lado y luego hacia el otro, y asiente como si le hubiera hablado.",
	["watches the space behind {target} for a long, slow moment, then looks back to the flames."] = "observa un buen rato el espacio detrás de {target}, y luego vuelve a mirar las llamas.",
	["watches the sparks climb until the last one goes out."] = "contempla cómo suben las chispas hasta que se apaga la última.",
	["watches the sparks go up into the dark and lets the moment hang."] = "mira cómo suben las chispas en la oscuridad y deja que el momento se alargue.",
	["watches the sparks lift off the fire and drift away into the dark, one by one."] = "mira cómo las chispas se levantan de la hoguera y se pierden en la oscuridad, una a una.",
	["watches which way the smoke leans, and does not remark on it."] = "observa hacia dónde se inclina el humo, y no comenta nada.",
	["waves a hand in front of their face and coughs politely."] = "se abanica la cara con la mano y tose con educación.",
	["waves a hand in front of their nose."] = "se abanica la nariz con la mano.",
	["weighs the seed over the flames for a moment, then closes their fingers around it and puts it away."] = "sopesa la semilla sobre las llamas un momento, luego cierra los dedos en torno a ella y la guarda.",
	["wets a finger, holds it up, and slowly turns to face the other way."] = "se moja un dedo, lo levanta y se gira despacio hacia el otro lado.",
	["whips an invisible rope around something twice and leans back hard with both hands."] = "da dos vueltas rápidas a una cuerda invisible alrededor de algo y se echa hacia atrás con fuerza, tirando con las dos manos.",
	["wiggles two fingers at the fire, and the flames happen to give a small, weary dance."] = "menea dos dedos hacia el fuego, y da la casualidad de que las llamas se marcan un bailecito cansado.",
	["winces at the memory, then laughs quietly to themselves."] = "hace una mueca al recordarlo y luego se ríe en voz baja.",
	["winds up and throws something hard and high, then holds very still, watching."] = "coge impulso y lanza algo fuerte y alto, y luego se queda mirando sin mover ni un músculo.",
	["wipes the last circle out of the ashes with one fingertip."] = "borra el último círculo de la ceniza con la yema de un dedo.",
	["wipes their hands slowly on their knees, as if they can't quite get them clean."] = "se limpia las manos despacio en las rodillas, como si no lograra dejarlas limpias del todo.",
	["wraps both hands around their cup with one thumb hooked over the rim, and looks at it."] = "rodea la taza con las dos manos, con un pulgar enganchado en el borde, y la mira.",
	["wraps one hand slowly around the other."] = "envuelve despacio una mano con la otra.",
	["wrenches an invisible rail free with both hands and drives it forward and down."] = "arranca un travesaño invisible con las dos manos y lo clava hacia delante y hacia abajo.",
	["wrings out the end of their sleeve and looks at it without hope."] = "escurre el extremo de la manga y lo mira sin ninguna esperanza.",
	["wrings out the hem of one sleeve, laughing."] = "escurre el bajo de una manga, riéndose.",
	["wrinkles their nose and holds an invisible shard at arm's length."] = "arruga la nariz y sostiene un fragmento invisible con el brazo bien estirado.",
	["wrinkles their nose and leans slowly away from their own armpit."] = "arruga la nariz y se aparta despacio de su propio sobaco.",
	["writes a line of small, tidy letters in the ashes with a stick, and leaves the last word unfinished."] = "escribe con un palito una línea de letras pequeñas y pulcras en la ceniza, y deja la última palabra a medias.",
	["yanks an invisible strap twice, then lets it go with a sigh."] = "da dos tirones a una correa invisible y luego la suelta con un suspiro.",
	["yanks one hand sharply backward, then stares at the empty space in front of them."] = "tira de una mano hacia atrás con brusquedad y luego mira fijamente el espacio vacío que tiene delante.",
	["yet hold me and wait, and I'll bring you back home. What am I?"] = "pero agárrame, espera, y a casa volverás. ¿Qué soy?",
	["your bags"] = "tu bolsa",
	["{target}, I should warn you. People have been talking."] = "{target}, tengo que avisarte. La gente habla.",
	["{target}, an old friend and I have argued for years over whether soup is a food or a drink. We've ruined a lot of good soup over it."] = "{target}, una vieja amiga y yo llevamos años discutiendo si la sopa se come o se bebe. Hemos echado a perder mucha sopa buena por culpa de eso.",
	["{target}, would you mind if I told you something about where you're sitting? It's nothing bad. Probably."] = "{target}, ¿te importa si te cuento algo sobre el sitio donde te has sentado? No es nada malo. Seguramente.",
	["{target}, you seem sensible, so I'll tell you what I tell everyone who eats at my fire."] = "{target}, pareces una persona sensata, así que te diré lo que le digo a todo el que come en mi hoguera.",
})
